def sbox_x5(state: list[int]) -> list[int]:
    """
    Passa o vetor de estado inteiro pelas S-Boxes (x^5 mod P).
    """
    new_state = []
    for x in state:
        # pow() calcula (x ** 5) % MODULUS internamente em C, super eficiente
        new_state.append(pow(x, 5, MODULUS))
    return new_state

def mds_mixing(state: list[int]) -> list[int]:
    """
    Multiplica o vetor de estado (9x1) pela MDS_MATRIX (9x9).
    A matemática é: NovoEstado[i] = Sum(MDS[i][j] * Estado[j]) mod P
    """
    t = len(state)
    new_state = []
    
    for i in range(t):
        tmp = 0
        for j in range(t):
            # Faz a multiplicação modular do coeficiente pelo valor do estado
            mult = (MDS_MATRIX[i][j] * state[j]) % MODULUS
            # Acumula e tira o módulo novamente para evitar estouro
            tmp = (tmp + mult) % MODULUS
        new_state.append(tmp)

    return new_state

